# -*- coding: utf-8 -*-
from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject
from taf.fdsw.rc.schemas.FDSW19.autoconnection import PnpProtocolParameters, PnpStatus


class CertificateServerParameters(SchemaObject):
    directory = SchemaField(name="directory")
    ip_address = SchemaField(name="ipAddress")
    subject_name = SchemaField(name="subjectName")
    vpn_gateway_ip_address = SchemaField(name="vpnGatewayIpAddress")
    server_port = SchemaField(name="serverPort")
    cmp_security_gateway_ip_address = SchemaField(name="cmpSecurityGatewayIpAddress")

    def __init__(
            self,
            directory,
            ip_address,
            subject_name,
            vpn_gateway_ip_address,
            server_port,
            cmp_security_gateway_ip_address
    ):
        self.directory = directory
        self.ip_address = ip_address
        self.subject_name = subject_name
        self.vpn_gateway_ip_address = vpn_gateway_ip_address
        self.server_port = server_port
        self.cmp_security_gateway_ip_address = cmp_security_gateway_ip_address
        super(CertificateServerParameters, self).__init__()


class ManagementPlaneParameters(SchemaObject):
    ip_address = SchemaField(name="ipAddress")
    prefix_length = SchemaField(name="prefixLength")
    gateway = SchemaField(name="gateway")
    vlan_id = SchemaField(name="vlanId")
    oms_ip_address = SchemaField(name="omsIpAddress")
    sec_ip_address = SchemaField(name="secIpAddress")
    sec_prefix_length = SchemaField(name="secPrefixLength")
    sec_vlan_id = SchemaField(name="secVlanId")
    inner_mplane_ip_address = SchemaField(name="innerMplaneIpAddress")

    def __init__(
            self,
            ip_address,
            prefix_length,
            gateway,
            vlan_id,
            oms_ip_address,
            sec_ip_address,
            sec_prefix_length,
            sec_vlan_id,
            inner_mplane_ip_address,
            inner_mplane_ip_version
    ):
        self.ip_address = ip_address
        self.prefix_length = prefix_length
        self.gateway = gateway
        self.vlan_id = vlan_id
        self.oms_ip_address = oms_ip_address
        self.sec_ip_address = sec_ip_address
        self.sec_prefix_length = sec_prefix_length
        self.sec_vlan_id = sec_vlan_id
        self.inner_mplane_ip_address = inner_mplane_ip_address
        self.inner_mplane_ip_version = inner_mplane_ip_version
        super(ManagementPlaneParameters, self).__init__()


class AutoConnection21A(SchemaObject):
    pnp_status = SchemaField(name="pnpStatus", klass=PnpStatus)
    management_plane_parameters = SchemaField(
        name="managementPlaneParameters",
        klass=ManagementPlaneParameters
    )
    certificate_server_parameters = SchemaField(
        name="certificateServerParameters",
        klass=CertificateServerParameters
    )
    pnp_protocol_parameters = SchemaField(
        name="pnpProtocolParameters",
        klass=PnpProtocolParameters
    )
    scenario = SchemaField(name='scenario', optional=True)

    def __init__(
            self,
            pnp_status,
            management_plane_parameters,
            pnp_protocol_parameters,
            certificate_server_parameters,
            scenario=None
    ):
        self.pnp_status = pnp_status
        self.management_plane_parameters = management_plane_parameters
        self.pnp_protocol_parameters = pnp_protocol_parameters
        self.certificate_server_parameters = certificate_server_parameters
        self.scenario = scenario

        super(AutoConnection21A, self).__init__()
